insert into public.dynamic_forms (slug, name, status, description)
values ('funnel-jkl-marcenaria', 'JKL Marcenaria', 'published', 'Funil individual de JKL Marcenaria')
on conflict (slug) do update
  set name = excluded.name,
      status = 'published',
      description = excluded.description;

DO $$ DECLARE v_form_id uuid; BEGIN SELECT id INTO v_form_id FROM public.dynamic_forms WHERE slug='funnel-jkl-marcenaria'; DELETE FROM public.dynamic_form_questions WHERE form_id=v_form_id; INSERT INTO public.dynamic_form_questions (form_id,key,type,label,order_index,required,options_json) VALUES (v_form_id,'welcome','statement','Vamos projetar seu ambiente ✨',0,false,'[]'::jsonb),(v_form_id,'nome','short_text','Qual é o seu nome?',1,true,'[]'::jsonb),(v_form_id,'servico','radio','Qual ambiente você quer transformar?',2,true,jsonb_build_array(jsonb_build_object('value','cozinha','label','Cozinha planejada em MDF'),jsonb_build_object('value','dormitorio','label','Guarda-roupa e dormitório'),jsonb_build_object('value','nichos','label','Nichos e porta-tempero'),jsonb_build_object('value','banheiro','label','Banheiro e ambientes em geral'))),(v_form_id,'projeto','radio','Conte sobre o projeto',3,true,jsonb_build_array(jsonb_build_object('value','completo','label','Projeto completo'),jsonb_build_object('value','sob-medida','label','Móvel sob medida'),jsonb_build_object('value','infantil','label','Cozinha infantil'),jsonb_build_object('value','renovar','label','Quero renovar um ambiente'))),(v_form_id,'local','radio','Onde será a instalação?',4,true,jsonb_build_array(jsonb_build_object('value','curitiba','label','Curitiba e região'),jsonb_build_object('value','confirmar','label','Vou confirmar o endereço'))),(v_form_id,'prazo','radio','Quando deseja receber?',5,true,jsonb_build_array(jsonb_build_object('value','20-dias','label','Quero aproveitar a entrega em até 20 dias'),jsonb_build_object('value','planejando','label','Estou planejando'),jsonb_build_object('value','avaliacao','label','Quero uma avaliação'))),(v_form_id,'detalhes','long_text','Mais detalhes','Medidas aproximadas, estilo e preferências ajudam.','Descreva seu projeto',6,false,'[]'::jsonb),(v_form_id,'telefone','phone','Qual WhatsApp para retorno?',7,true,'[]'::jsonb),(v_form_id,'confirmacao','statement','Solicitação recebida! ✅','A JKL confirmará os próximos passos.',8,false,'[]'::jsonb); END $$;
